public class Crowd : MonoBehaviour
{
    NativeArray<float3> pos, vel;   // allocated in Awake
    NativeArray<int> cell;
    JobHandle handle;

    void Update()
    {
        int n = pos.Length;
        var move    = new MoveJob    { pos = pos, vel = vel, dt = Time.deltaTime };
        var hash    = new HashJob    { pos = pos, cell = cell };
        var collide = new CollideJob { pos = pos, cell = cell, vel = vel };

        JobHandle h = move.Schedule(n, 64);
        h = hash.Schedule(n, 64, h);           // after MoveJob
        handle = collide.Schedule(n, 64, h);   // after HashJob
        JobHandle.ScheduleBatchedJobs();       // wake the workers
    }

    void LateUpdate()
    {
        handle.Complete();   // completes the whole chain
    }
}
